INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (1579,'2026-08-13T22:20:45+0800','ai_chinese_relayout','deepseek-v4-flash-ga-260731','你是一个只输出JSON的小学语文排版整理器。','你是小学语文排版整理器。下面是一段从课本照片识别出来的文字（可能含乱码残留、重复行、段落粘连）。
