INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (1580,'2026-08-13T22:20:52+0800','ai_chinese_classify','deepseek-v4-flash-ga-260731','你是一个只输出JSON的小学语文教研员。','你是小学语文教研员。下面是从语文课本/练习册拍摄页面识别的文本。
