INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (2059,'2026-08-14T19:08:49+0800','ai_chinese_highlight','deepseek-v4-flash-ga-260731','你是一个只输出JSON的小学语文老师。','你是小学语文老师。下面是一篇课文/短文。请依据【3】年级语文学习重点，标注值得学习的：
