INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (2225,'2026-08-15T17:39:42+0800','essay_hint','deepseek-v4-flash-ga-260731','你是面向小学生的写作思维教练。请根据作文题目、当前段落要求、学生已说内容，生成一个紧凑的写作提示。
