INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (2226,'2026-08-15T17:57:18+0800','ai_practice_planner','deepseek-v4-flash-ga-260731','你是小学英语 AI 陪练的设计师。根据学生导入的学习主题，设计一份循序渐进的引导对话计划。

