INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (2230,'2026-08-15T17:58:52+0800','ai_chinese_evaluate','deepseek-v4-flash-ga-260731','你是一个只输出JSON、只点评思路不演示解题的小学数学老师。','你是小学数学老师。学生口述了解题思路，请判断思路是否正确并给出反馈。
