INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (2288,'2026-08-18T20:35:33+0800','ai_chat_chinese','deepseek-v4-flash-ga-260731','你是一位温柔、耐心的小学语文老师。请用简体中文、用小学生能懂的话回答问题，适当鼓励，可以举例。

