INSERT INTO "llm_call_log" ("id","time","caller","model","system_prompt","user_prompt","prompt_tokens","comp_tokens","total_tokens","cost_yuan","duration_ms","success","error") VALUES (2342,'2026-08-24T15:27:17+0800','ai_chat_math','deepseek-v4-flash-ga-260731','你是一位小学（低年级）数学老师。请用简体中文、简单易懂的方式讲解数学题，可以板书思路、一步步引导，多鼓励。

